 public string Selected=>selected;public string Filter=>filter;public int VisibleCount=>rows.Count;public RiftModelView Preview=>preview;
 public static string Category(RiftAchievementDefinition a){switch(a.Criterion.Event){case RiftProgressEvent.Kill:case RiftProgressEvent.MiniBoss:case RiftProgressEvent.TrainingHit:return "Combate";case RiftProgressEvent.Checkpoint:case RiftProgressEvent.Encounter:return "Exploración";case RiftProgressEvent.QuestTurnedIn:return "Misiones";case RiftProgressEvent.Talk:return "Social";case RiftProgressEvent.Collect:return "Colección";default:return "Otros";}}
 public void Build(RiftHub owner,JournalState journal,RiftJournalCatalog catalog,Action close,int skin){hub=owner;state=journal??new JournalState();definitions=catalog.Achievements.Where(a=>a&&a.Criterion!=null).ToArray();var root=(RectTransform)transform;var panel=RiftModernWidgets.Panel(root,"Achievement glass",0,0,1190,870);panel.GetComponent<Image>().color=new Color(.018f,.019f,.032f,.74f);panel.GetComponent<Image>().raycastTarget=true;
 Icon(panel,HUDShape.Diamond,24,24,34,Violet);Label(panel,"Logros",78,15,700,60,38,Bright);var exit=RiftModernWidgets.Button(panel,"×",1116,23,48,45,close);exit.name="Close achievements";
