 var names=new[]{"Todos"}.Concat(definitions.Select(Category).Distinct()).ToArray();float tabWidth=Mathf.Min(216,1136f/names.Length);for(int i=0;i<names.Length;i++){string c=names[i];var b=RiftModernWidgets.Button(panel,c,24+i*tabWidth,131,tabWidth-8,44,()=>SetCategory(c));b.name="Achievement category "+c;categories[c]=b;var tabLabel=b.GetComponentInChildren<Text>();tabLabel.rectTransform.anchoredPosition=new Vector2(46,0);tabLabel.rectTransform.sizeDelta=new Vector2(tabWidth-62,44);tabLabel.alignment=TextAnchor.MiddleLeft;Icon(b.transform,CategoryShape(c),14,10,24,new Color(.76f,.72f,.88f));}
 list=RiftWidgets.ScrollArea(panel,"Achievement cards",24,196,635,580,definitions.Length*146);scroll=list.GetComponentInParent<ScrollRect>();RiftWidgets.Image(panel,"Detail divider",679,196,1,580,new Color(.38f,.38f,.48f,.4f));detail=RiftWidgets.Rect(panel,"Selected achievement",706,196,438,580);
 Label(panel,"Tab / flechas: seleccionar  ·  Enter: activar",26,812,850,30,16,Muted);Label(panel,"Esc: cerrar",1015,812,140,30,16,Muted);
 var stage=RiftWidgets.Rect(root,"Achievement character",1206,-40,610,900);preview=RiftModelView.Create(stage,0,0,610,800,null,false);var actor=ClientFrontend.ClientPlayerInstance?ClientFrontend.ClientPlayerInstance.MyCharacter:null;if(actor){preview.ShowLiveCharacter(actor);Label(stage,actor.Health.CharacterName,30,86,550,48,36,Bright).alignment=TextAnchor.MiddleCenter;}else{var model=hub.Catalog?hub.Catalog.Characters.FirstOrDefault(m=>m.SkinIndex==skin):null;if(model!=null)preview.Show(model);Label(stage,MultiFPS.Gameplay.RiftCombat.RiftSkinIdentity.Name(skin),30,86,550,48,36,Bright).alignment=TextAnchor.MiddleCenter;}Label(stage,"Warrior",30,138,550,30,19,Muted).alignment=TextAnchor.MiddleCenter;Rebuild();}
 public void SetCategory(string value){if(!categories.ContainsKey(value))return;filter=value;Rebuild();}
 public void Select(string id){if(!rows.ContainsKey(id))return;selected=id;foreach(var pair in rows){var outline=pair.Value.GetComponent<Outline>();if(outline)outline.effectColor=pair.Key==id?new Color(.66f,.44f,.96f,.9f):new Color(.4f,.4f,.5f,.3f);}DrawDetail();var row=(RectTransform)rows[id].transform;float top=-row.anchoredPosition.y,offset=list.anchoredPosition.y;if(top<offset)list.anchoredPosition=new Vector2(0,top);else if(top+132>offset+580)list.anchoredPosition=new Vector2(0,top+132-580);}
 void Rebuild(){foreach(Transform child in list)Destroy(child.gameObject);rows.Clear();foreach(var c in categories)RiftModernWidgets.Tab(c.Value,c.Key==filter);var visible=definitions.Where(a=>filter=="Todos"||Category(a)==filter).ToArray();list.sizeDelta=new Vector2(635,Mathf.Max(580,visible.Length*146));list.anchoredPosition=Vector2.zero;for(int i=0;i<visible.Length;i++){var a=visible[i];bool done=state.Achievements.Any(r=>r.Id==a.Id);int count=Mathf.Clamp(state.Count(a.Criterion),0,a.Criterion.Required);var b=RiftModernWidgets.Button(list,"",0,i*146,615,132,()=>Select(a.Id));b.name="Achievement "+a.Id;b.GetComponentInChildren<Text>().gameObject.SetActive(false);rows[a.Id]=b;var palette=b.colors;palette.normalColor=new Color(.035f,.036f,.055f,.64f);palette.highlightedColor=new Color(.085f,.065f,.14f,.8f);palette.selectedColor=new Color(.10f,.065f,.18f,.82f);palette.pressedColor=new Color(.13f,.075f,.22f,.86f);b.colors=palette;var row=b.gameObject.AddComponent<RiftAchievementRow>();row.View=this;row.Id=a.Id;AchievementIcon(b.transform,a,18,22,76,done,true);Label(b.transform,a.Title,110,9,485,43,23,Bright);Label(b.transform,Category(a),110,58,265,25,16,Muted);var status=Label(b.transform,done?"Completado":count>0?"En progreso":"Sin iniciar",392,57,203,24,16,done?Complete:Muted);status.alignment=TextAnchor.MiddleRight;Label(b.transform,count+" / "+a.Criterion.Required,486,82,109,23,18,Bright).alignment=TextAnchor.MiddleRight;Bar(b.transform,110,111,485,7,done?1:(float)count/Mathf.Max(1,a.Criterion.Required),done?Complete:Violet);var tip=b.gameObject.AddComponent<RiftTooltipTrigger>();tip.Title=a.Title;tip.Description=a.Description+"\n"+count+" / "+a.Criterion.Required+" · "+a.Points+" puntos";}
 if(visible.Length==0){Label(list,"No hay logros en esta categoría.",12,30,600,90,23,Muted);ClearDetail();return;}if(!rows.ContainsKey(selected))selected=visible[0].Id;Select(selected);}
 void ClearDetail(){foreach(Transform child in detail)Destroy(child.gameObject);}
 void DrawDetail(){ClearDetail();var a=definitions.FirstOrDefault(d=>d.Id==selected);if(!a)return;var unlocked=state.Achievements.FirstOrDefault(r=>r.Id==a.Id);int count=Mathf.Clamp(state.Count(a.Criterion),0,a.Criterion.Required);bool done=unlocked!=null;AchievementIcon(detail,a,141,0,156,done,false);Label(detail,a.Title,0,166,438,80,30,Bright).alignment=TextAnchor.MiddleCenter;Label(detail,done?"Completado":count>0?"En progreso":"Sin iniciar",0,248,438,28,18,done?Complete:Violet).alignment=TextAnchor.MiddleCenter;RiftWidgets.Image(detail,"Divider",0,288,438,1,new Color(.4f,.4f,.5f,.4f));Label(detail,a.Description,0,306,438,88,21,Bright);Label(detail,a.Criterion.Label,0,409,295,32,18,Muted);Label(detail,count+" / "+a.Criterion.Required,300,409,138,32,21,Bright).alignment=TextAnchor.MiddleRight;Bar(detail,0,452,438,8,done?1:(float)count/Mathf.Max(1,a.Criterion.Required),done?Complete:Violet);Label(detail,a.Points+" puntos de logro",0,492,438,40,24,Violet);Label(detail,done?"Desbloqueado el "+DateTimeOffset.FromUnixTimeSeconds(unlocked.UnlockedAt).ToLocalTime().ToString("dd/MM/yyyy"):"El progreso se registra al jugar.",0,541,438,45,17,Muted);}
 // Optional sprite sheet: Resources/RiftAchievements/AchievementIcons, sliced sprites named by stable achievement ID.
 static Sprite[] achievementSprites;static Texture2D achievementAtlas;const bool AchievementAtlasApproved=true;
 static readonly string[] AchievementIconIds={"first-training","first-kill","ten-kills","three-crystals","first-boss","first-quest","village-friends"};
 static void AchievementIcon(Transform parent,RiftAchievementDefinition definition,float x,float y,float size,bool completed,bool card){
  if(achievementSprites==null)achievementSprites=Resources.LoadAll<Sprite>("RiftAchievements/AchievementIcons");
  var sprite=achievementSprites.FirstOrDefault(s=>s&&s.name==definition.Id);
  if(sprite){var image=RiftWidgets.Image(parent,"Achievement art "+definition.Id,x,y,size,size,Color.white,sprite);image.preserveAspect=true;image.raycastTarget=false;}
  else if((AchievementAtlasApproved||(Application.isEditor&&System.Environment.GetCommandLineArgs().Contains("-riftAchievementArtReview")))&&TryAtlasIcon(parent,definition.Id,x,y,size)){}
  else Icon(parent,card&&completed?HUDShape.Diamond:Shape(definition),x,y,size,completed?Complete:Violet);
 }
 static bool TryAtlasIcon(Transform parent,string id,float x,float y,float size){int cell=Array.IndexOf(AchievementIconIds,id);if(cell<0)return false;if(!achievementAtlas)achievementAtlas=Resources.Load<Texture2D>("RiftAchievements/AchievementIcons");if(!achievementAtlas)return false;float insetX=1f/achievementAtlas.width,insetY=1f/achievementAtlas.height;var image=RiftWidgets.Rect(parent,"Achievement art "+id,x,y,size,size).gameObject.AddComponent<RawImage>();image.texture=achievementAtlas;image.uvRect=new Rect((cell%4)*.25f+insetX,cell<4?.5f+insetY:insetY,.25f-2*insetX,.5f-2*insetY);image.raycastTarget=false;return true;}
 static HUDShape CategoryShape(string category){switch(category){case "Todos":return HUDShape.Bag;case "Combate":return HUDShape.Skill;case "Exploración":return HUDShape.Target;case "Misiones":return HUDShape.Diamond;case "Social":return HUDShape.Portrait;default:return HUDShape.Crystal;}}
 static HUDShape Shape(RiftAchievementDefinition a){switch(Category(a)){case "Combate":return HUDShape.Skill;case "Exploración":return HUDShape.Target;case "Misiones":return HUDShape.Diamond;case "Social":return HUDShape.Portrait;default:return HUDShape.Crystal;}}
 static void Icon(Transform parent,HUDShape shape,float x,float y,float size,Color color){var g=RiftWidgets.Rect(parent,"Achievement icon",x,y,size,size).gameObject.AddComponent<RiftHUDGraphic>();g.Shape=shape;g.color=color;g.Border=color;g.raycastTarget=false;}
 static Text Label(Transform p,string text,float x,float y,float w,float h,int size,Color color)=>RiftWidgets.Label(p,text,x,y,w,h,size,color);
 static void Bar(Transform p,float x,float y,float w,float h,float value,Color color){RiftWidgets.Image(p,"Progress track",x,y,w,h,new Color(.24f,.23f,.34f,.6f));RiftWidgets.Image(p,"Actual progress",x,y,w*Mathf.Clamp01(value),h,color);}
 void OnDisable(){if(preview)preview.SetRenderActive(false);}
}
